def styled_tab_trigger(label: str, value: str) -> rx.Component:
    base_tab_style = {
        "width": "flex-1",
        "border": "none",
        "background": "transparent",
        "&[data-state=active]": {
            "border": "none",
            "borderBottom": "1.25px solid black",
            "background": "transparent",
        },
        ".dark &[data-state=active]": {
            "borderBottom": "1.25px solid white",
        },
        "&[data-state=inactive]": {
            "border": "none",
            "background": "transparent",
        },
        "&::before": {
            "display": "none",
        },
    }

    return rx.tabs.trigger(rx.el.p(label), value=value, style=base_tab_style)


